package com.asmj.marketplace.discovery;

import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.service.CloudinaryImageService;
import org.springframework.web.multipart.MultipartFile;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class MarketplaceExtensionsController {
 private final MarketplaceExtensionListingRepository listings; private final MarketplaceExtensionRequestRepository requests; private final UserAccountRepository users; private final MarketplaceModuleCategoryRepository moduleCategories; private final CloudinaryImageService images; private final EventBookingSettingsRepository eventSettings; private final MarketplaceFinancialEntryRepository financialEntries;
 private static final Map<String,String> TYPES=Map.of("EVENT","events","COURSE","courses","WHOLESALE","wholesale","DELIVERY","delivery","FREELANCE","freelancers","BUSINESS","businesses","CLASSIFIED","classifieds");
 private static final Map<String,String> TITLES=Map.of("EVENT","Events & ticket booking","COURSE","Courses & training","WHOLESALE","Wholesale & B2B enquiries","DELIVERY","Local delivery & logistics","FREELANCE","Freelance & professional portfolio","BUSINESS","Business Directory","CLASSIFIED","Classifieds");
 public MarketplaceExtensionsController(MarketplaceExtensionListingRepository l,MarketplaceExtensionRequestRepository r,UserAccountRepository u,MarketplaceModuleCategoryRepository c,CloudinaryImageService images,EventBookingSettingsRepository eventSettings,MarketplaceFinancialEntryRepository financialEntries){listings=l;requests=r;users=u;moduleCategories=c;this.images=images;this.eventSettings=eventSettings;this.financialEntries=financialEntries;}
 private UserAccount user(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private String clean(String v,int n){if(v==null)return "";v=v.trim();return v.length()>n?v.substring(0,n):v;}
 private boolean validType(String type){return TYPES.containsKey(type);}
 private String browse(String type,String q,String city,Model m){List<MarketplaceExtensionListing> rows=listings.findByTypeAndStatusOrderByCreatedAtDesc(type,"APPROVED");if(q!=null&&!q.isBlank())rows.removeIf(x->!(safe(x.getTitle())+" "+safe(x.getCategory())+" "+safe(x.getDescription())+" "+safe(x.getSkills())).toLowerCase().contains(q.trim().toLowerCase()));if(city!=null&&!city.isBlank())rows.removeIf(x->x.getCity()==null||!x.getCity().equalsIgnoreCase(city.trim()));m.addAttribute("items",rows);m.addAttribute("type",type);m.addAttribute("moduleTitle",TITLES.get(type));m.addAttribute("q",q);m.addAttribute("city",city);return "extensions/list";}
 private String safe(String s){return s==null?"":s;}
 @GetMapping("/events") public String events(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("EVENT",q,city,m);}
 @GetMapping("/courses") public String courses(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("COURSE",q,city,m);}
 @GetMapping("/wholesale") public String wholesale(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("WHOLESALE",q,city,m);}
 @GetMapping("/delivery") public String delivery(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("DELIVERY",q,city,m);}
 @GetMapping("/freelancers") public String freelancers(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("FREELANCE",q,city,m);}
 @GetMapping("/api/marketplace/categories") @ResponseBody public List<Map<String,Object>> moduleCategoryOptions(@RequestParam String type){
  if(!validType(type))return List.of();
  return moduleCategories.findByTypeAndActiveTrueOrderByNameAsc(type).stream().map(c->{Map<String,Object> row=new LinkedHashMap<>();row.put("name",c.getName());row.put("subcategories",c.getSubcategories());return row;}).toList();
 }
 @GetMapping("/marketplace/new/{type}") public String create(@PathVariable String type,Model m){if(!validType(type))return "error";m.addAttribute("type",type);m.addAttribute("moduleTitle",TITLES.get(type));m.addAttribute("listing",new MarketplaceExtensionListing());m.addAttribute("moduleCategories",moduleCategories.findByTypeAndActiveTrueOrderByNameAsc(type));return "extensions/form";}
 @GetMapping("/marketplace/{id}/edit") public String edit(@PathVariable String id,Authentication auth,Model m,RedirectAttributes ra){
  UserAccount current=user(auth); MarketplaceExtensionListing item=listings.findById(id).orElse(null);
  if(item==null || !current.getId().equals(item.getOwnerUserId())){ra.addFlashAttribute("error","This listing was not found in your account.");return "redirect:/my-marketplace-listings";}
  if("APPROVED".equalsIgnoreCase(item.getStatus())){ra.addFlashAttribute("error","Approved listings cannot be edited. Please contact Admin if a correction is required.");return "redirect:/my-marketplace-listings";}
  m.addAttribute("type",item.getType());m.addAttribute("moduleTitle",TITLES.getOrDefault(item.getType(),item.getType()));m.addAttribute("listing",item);m.addAttribute("editing",true);m.addAttribute("moduleCategories",moduleCategories.findByTypeAndActiveTrueOrderByNameAsc(item.getType()));return "extensions/form";
 }
 @PostMapping("/marketplace/{id}/delete") public String delete(@PathVariable String id,Authentication auth,RedirectAttributes ra){
  UserAccount current=user(auth); MarketplaceExtensionListing item=listings.findById(id).orElse(null);
  if(item==null || !current.getId().equals(item.getOwnerUserId())){ra.addFlashAttribute("error","This listing was not found in your account.");return "redirect:/my-marketplace-listings";}
  if("APPROVED".equalsIgnoreCase(item.getStatus())){ra.addFlashAttribute("error","Approved listings cannot be deleted. Please contact Admin if removal is required.");return "redirect:/my-marketplace-listings";}
  listings.delete(item);ra.addFlashAttribute("success","Your unapproved listing has been deleted.");return "redirect:/my-marketplace-listings";
 }
 @PostMapping("/marketplace/save") public String save(@RequestParam String type,@RequestParam String title,@RequestParam String category,@RequestParam(required=false) String subcategory,@RequestParam String description,@RequestParam(required=false)String organisation,@RequestParam(required=false)String contactName,@RequestParam(required=false)String contactMobile,@RequestParam(required=false)String website,@RequestParam(required=false) MultipartFile imageFile,@RequestParam(required=false)String address,@RequestParam(required=false)String city,@RequestParam(required=false)String state,@RequestParam(required=false)String pinCode,@RequestParam(required=false)String deliveryArea,@RequestParam(required=false)String mode,@RequestParam(required=false)String skills,@RequestParam(required=false)String duration,@RequestParam(required=false)String schedule,@RequestParam(required=false)String venue,@RequestParam(required=false)String portfolioUrl,@RequestParam(required=false)String courseLevel,@RequestParam(required=false)String employmentType,@RequestParam(required=false)String price,@RequestParam(required=false)String minOrderQuantity,@RequestParam(required=false)Integer capacity,@RequestParam(required=false)Integer availableQuantity,@RequestParam(required=false,defaultValue="false") boolean onlineBookingEnabled,@RequestParam(required=false)String eventDate,@RequestParam(required=false)String startDate,@RequestParam(required=false)String endDate,@RequestParam(required=false)String listingId,Authentication auth,RedirectAttributes ra){if(!validType(type))return "redirect:/";UserAccount current=user(auth);MarketplaceExtensionListing x;if(listingId!=null&&!listingId.isBlank()){x=listings.findById(listingId).orElse(null);if(x==null||!current.getId().equals(x.getOwnerUserId())){ra.addFlashAttribute("error","Listing not found in your account.");return "redirect:/my-marketplace-listings";}if("APPROVED".equalsIgnoreCase(x.getStatus())){ra.addFlashAttribute("error","Approved listings cannot be edited.");return "redirect:/my-marketplace-listings";}if(!type.equals(x.getType())){ra.addFlashAttribute("error","Listing type cannot be changed.");return "redirect:/my-marketplace-listings";}}else{x=new MarketplaceExtensionListing();x.setType(type);x.setOwnerUserId(current.getId());}x.setTitle(clean(title,150));x.setCategory(clean(category,100));x.setSubcategory(clean(subcategory,100));x.setDescription(clean(description,5000));
 MarketplaceModuleCategory selectedCategory=moduleCategories.findByTypeAndActiveTrueOrderByNameAsc(type).stream().filter(c->c.getName().equals(clean(category,100))).findFirst().orElse(null);
 if(selectedCategory==null || (!x.getSubcategory().isBlank()&&!selectedCategory.getSubcategories().contains(x.getSubcategory()))){ra.addFlashAttribute("error","Please select a valid active category and subcategory.");return listingId!=null&&!listingId.isBlank()?"redirect:/marketplace/"+listingId+"/edit":"redirect:/marketplace/new/"+type;}
 if(imageFile!=null&&!imageFile.isEmpty()){try{Map<String,Object> uploaded=images.uploadMarketplaceImage(imageFile,type.toLowerCase(Locale.ROOT));x.setImageUrl(String.valueOf(uploaded.get("secure_url")));}catch(Exception ex){ra.addFlashAttribute("error",ex.getMessage());return listingId!=null&&!listingId.isBlank()?"redirect:/marketplace/"+listingId+"/edit":"redirect:/marketplace/new/"+type;}}x.setOrganisation(clean(organisation,160));x.setContactName(clean(contactName,100));x.setContactMobile(clean(contactMobile,20));x.setWebsite(clean(website,300));x.setAddress(clean(address,300));x.setCity(clean(city,80));x.setState(clean(state,80));x.setPinCode(clean(pinCode,10));x.setDeliveryArea(clean(deliveryArea,500));x.setMode(clean(mode,80));x.setSkills(clean(skills,1000));x.setDuration(clean(duration,100));x.setSchedule(clean(schedule,300));x.setVenue(clean(venue,250));x.setPortfolioUrl(clean(portfolioUrl,500));x.setCourseLevel(clean(courseLevel,80));x.setEmploymentType(clean(employmentType,80));try{if(price!=null&&!price.isBlank())x.setPrice(new BigDecimal(price));if(minOrderQuantity!=null&&!minOrderQuantity.isBlank())x.setMinOrderQuantity(new BigDecimal(minOrderQuantity));if(eventDate!=null&&!eventDate.isBlank())x.setEventDate(LocalDate.parse(eventDate));if(startDate!=null&&!startDate.isBlank())x.setStartDate(LocalDate.parse(startDate));if(endDate!=null&&!endDate.isBlank())x.setEndDate(LocalDate.parse(endDate));}catch(Exception ex){ra.addFlashAttribute("error","Please check the entered price or date fields.");return listingId!=null&&!listingId.isBlank()?"redirect:/marketplace/"+listingId+"/edit":"redirect:/marketplace/new/"+type;}x.setCapacity(capacity);x.setAvailableQuantity(availableQuantity);x.setOnlineBookingEnabled("EVENT".equals(type)&&onlineBookingEnabled);if("EVENT".equals(type)&&capacity!=null&&capacity>0&&x.getAvailableQuantity()==null)x.setAvailableQuantity(capacity);if(x.getTitle().isBlank()||x.getCategory().isBlank()||x.getDescription().isBlank()){ra.addFlashAttribute("error","Title, category and description are required.");return listingId!=null&&!listingId.isBlank()?"redirect:/marketplace/"+listingId+"/edit":"redirect:/marketplace/new/"+type;}x.setStatus("PENDING");if(x.getCreatedAt()==null)x.setCreatedAt(Instant.now());x.setUpdatedAt(Instant.now());listings.save(x);ra.addFlashAttribute("success","Your submission has been saved and is pending admin approval.");return "redirect:/my-marketplace-listings";}
 @PostMapping("/marketplace/{id}/request") public synchronized String request(@PathVariable String id,@RequestParam(required=false)String message,@RequestParam(required=false)String quantity,@RequestParam(required=false)String pickupAddress,@RequestParam(required=false)String dropAddress,Authentication auth,RedirectAttributes ra){MarketplaceExtensionListing l=listings.findById(id).orElse(null);if(l==null||!"APPROVED".equals(l.getStatus()))return "redirect:/";UserAccount u=user(auth);MarketplaceExtensionRequest r=new MarketplaceExtensionRequest();r.setListingId(id);r.setType(l.getType());r.setRequesterUserId(u.getId());r.setRequesterName(u.getFullName());r.setRequesterEmail(u.getEmail());r.setMessage(clean(message,2000));r.setQuantity(clean(quantity,80));if("EVENT".equals(l.getType())){if(!l.isOnlineBookingEnabled()){ra.addFlashAttribute("error","This event accepts bookings directly with the organizer and does not use ASMJ Shoppe online booking.");return "redirect:/events";} }if("EVENT".equals(l.getType())){int ticketCount=1;try{ticketCount=(quantity==null||quantity.isBlank())?1:Integer.parseInt(quantity);}catch(NumberFormatException ex){ra.addFlashAttribute("error","Enter a valid ticket quantity.");return "redirect:/events";}if(ticketCount<1||(l.getAvailableQuantity()!=null&&ticketCount>l.getAvailableQuantity())){ra.addFlashAttribute("error","Requested ticket quantity is not available.");return "redirect:/events";}if(l.getPrice()==null||l.getPrice().signum()<0){ra.addFlashAttribute("error","This event does not have a valid ticket price configured.");return "redirect:/events";}r.setUnitPrice(l.getPrice());r.setCustomerAmount(l.getPrice().multiply(BigDecimal.valueOf(ticketCount)));r.setCustomerPaymentStatus("PAYABLE_TO_VENDOR");EventBookingSettings cfg=eventSettings.findById("default").orElseGet(EventBookingSettings::new);BigDecimal fixed=BigDecimal.ZERO,pct=BigDecimal.ZERO,fee=BigDecimal.ZERO;if(cfg.isEnabled()){if("FIXED".equals(cfg.getChargeMode())||"BOTH".equals(cfg.getChargeMode()))fixed=cfg.getFixedCharge()==null?BigDecimal.ZERO:cfg.getFixedCharge();if("PERCENTAGE".equals(cfg.getChargeMode())||"BOTH".equals(cfg.getChargeMode()))pct=cfg.getPercentageCharge()==null?BigDecimal.ZERO:cfg.getPercentageCharge();fee=fixed.add(r.getCustomerAmount().multiply(pct).divide(new BigDecimal("100"),2,java.math.RoundingMode.HALF_UP));}r.setMarketplaceFixedCharge(fixed);r.setMarketplacePercentageCharge(pct);r.setMarketplaceChargeAmount(fee);r.setMarketplaceChargeStatus(fee.signum()>0?"PENDING_VENDOR_CONFIRMATION":"NOT_APPLICABLE");if(l.getAvailableQuantity()!=null){l.setAvailableQuantity(l.getAvailableQuantity()-ticketCount);listings.save(l);}r.setQuantity(String.valueOf(ticketCount));}r.setPickupAddress(clean(pickupAddress,300));r.setDropAddress(clean(dropAddress,300));r.setStatus("SUBMITTED");requests.save(r);ra.addFlashAttribute("success",switch(l.getType()){case "EVENT"->"Event registration request submitted. The organizer will confirm availability and payment instructions.";case "COURSE"->"Course enrolment enquiry submitted.";case "WHOLESALE"->"Wholesale quotation request sent.";case "DELIVERY"->"Delivery request submitted for provider confirmation.";default->"Project enquiry sent to the professional.";});return "redirect:/"+TYPES.get(l.getType());}
 @GetMapping("/my-marketplace-listings") public String mine(Authentication a,Model m){UserAccount current=user(a);m.addAttribute("items",listings.findByOwnerUserIdOrderByCreatedAtDesc(current.getId()));m.addAttribute("requests",requests.findByRequesterUserIdOrderByCreatedAtDesc(current.getId()));return "extensions/mine";}
 @GetMapping("/my-marketplace-listings/{id}") public String myListingDetails(@PathVariable String id,Authentication a,Model m,RedirectAttributes ra){
  UserAccount current=user(a); MarketplaceExtensionListing item=listings.findById(id).orElse(null);
  if(item==null || !current.getId().equals(item.getOwnerUserId())){ra.addFlashAttribute("error","This submission could not be found in your account.");return "redirect:/my-marketplace-listings";}
  m.addAttribute("item",item);m.addAttribute("requests",requests.findByListingIdOrderByCreatedAtDesc(id));m.addAttribute("moduleTitle",TITLES.getOrDefault(item.getType(),item.getType()));return "extensions/detail";
 }
 @GetMapping("/vendor/marketplace-requests/{id}") public String vendorRequestDetails(@PathVariable String id,Authentication a,Model m,RedirectAttributes ra){
  UserAccount current=user(a); MarketplaceExtensionRequest request=requests.findById(id).orElse(null);
  if(request==null){ra.addFlashAttribute("error","Request not found.");return "redirect:/my-marketplace-listings";}
  MarketplaceExtensionListing item=listings.findById(request.getListingId()).orElse(null);
  if(item==null || !current.getId().equals(item.getOwnerUserId())){ra.addFlashAttribute("error","You are not allowed to view this request.");return "redirect:/my-marketplace-listings";}
  m.addAttribute("request",request);m.addAttribute("item",item);return "extensions/request-detail";
 }
 @GetMapping("/admin/marketplace-extensions") public String admin(Model m){m.addAttribute("items",listings.findAll());m.addAttribute("requests",requests.findAll());return "extensions/admin";}
 @PostMapping("/admin/marketplace-extensions/{id}/status") public String status(@PathVariable String id,@RequestParam String status,RedirectAttributes ra){if(!Set.of("APPROVED","REJECTED","SUSPENDED","CLOSED").contains(status))return "redirect:/admin/marketplace-extensions";listings.findById(id).ifPresent(x->{x.setStatus(status);x.setUpdatedAt(Instant.now());listings.save(x);});ra.addFlashAttribute("success","Marketplace submission status updated.");return "redirect:/admin/marketplace-extensions";}
 @PostMapping("/admin/marketplace-extension-requests/{id}/status") public String requestStatus(@PathVariable String id,@RequestParam String status,RedirectAttributes ra){if(!Set.of("CONFIRMED","IN_PROGRESS","COMPLETED","CANCELLED","QUOTED").contains(status))return "redirect:/admin/marketplace-extensions";requests.findById(id).ifPresent(x->{String previous=x.getStatus();if("EVENT".equals(x.getType())&&"SUBMITTED".equals(previous)&&"CANCELLED".equals(status)){listings.findById(x.getListingId()).ifPresent(event->{if(event.getAvailableQuantity()!=null){int count=1;try{count=Integer.parseInt(x.getQuantity());}catch(Exception ignored){}event.setAvailableQuantity(event.getAvailableQuantity()+count);listings.save(event);}});}x.setStatus(status);if("CONFIRMED".equals(status)&&"EVENT".equals(x.getType())&&(x.getTicketReference()==null||x.getTicketReference().isBlank()))x.setTicketReference("ASMJ-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT));if("CONFIRMED".equals(status)&&"EVENT".equals(x.getType())&&x.getMarketplaceChargeAmount()!=null&&x.getMarketplaceChargeAmount().signum()>0&&"PENDING_VENDOR_CONFIRMATION".equals(x.getMarketplaceChargeStatus())){MarketplaceExtensionListing event=listings.findById(x.getListingId()).orElse(null);if(event!=null && financialEntries.findByReferenceIdAndComponent(x.getId(),"EVENT_BOOKING_PLATFORM_CHARGE").isEmpty()){MarketplaceFinancialEntry entry=new MarketplaceFinancialEntry();entry.setModuleType("EVENT");entry.setReferenceId(x.getId());entry.setReferenceNumber(x.getTicketReference());entry.setComponent("EVENT_BOOKING_PLATFORM_CHARGE");entry.setPayerType("VENDOR");entry.setPayerId(event.getOwnerUserId());entry.setPayeeType("MARKETPLACE");entry.setPayeeId("ASMJ_MARKETPLACE");entry.setAmount(x.getMarketplaceChargeAmount());entry.setPaymentStatus("PAYABLE");entry.setSettlementStatus("UNSETTLED");financialEntries.save(entry);x.setMarketplaceChargeStatus("PAYABLE_BY_VENDOR");}}x.setUpdatedAt(Instant.now());requests.save(x);});ra.addFlashAttribute("success","Request status updated.");return "redirect:/admin/marketplace-extensions";}
 @GetMapping("/marketplace-extension-requests") public String myRequests(Authentication a,Model m){m.addAttribute("requests",requests.findByRequesterUserIdOrderByCreatedAtDesc(user(a).getId()));return "extensions/requests";}
}
